param([switch]$Child,[string]$OutputPath='')

$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$here=Split-Path -Parent $MyInvocation.MyCommand.Path
$controller=Join-Path $here 'v16_recovery_controller.ps1'

function Get-Hash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}

if($Child){
    . $controller
    $fixture=Join-Path ([IO.Path]::GetTempPath()) ('v16-real-controller-fixture-'+[Guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $fixture -Force|Out-Null
    $logs=Join-Path $fixture 'logs';New-Item -ItemType Directory -Path $logs -Force|Out-Null
    $trace=[Collections.Generic.List[object]]::new()
    $trace.Add([pscustomobject]@{phase='bootstrap';fixture_root=$fixture;controller_path=$controller;controller_sha256=(Get-Hash $controller);powershell=$PSHOME;is_64_bit=[Environment]::Is64BitProcess;pid=[Diagnostics.Process]::GetCurrentProcess().Id})

    $entryOut=Join-Path $logs 'controller-entry.stdout.txt';$entryErr=Join-Path $logs 'controller-entry.stderr.txt';$entryPsi=New-Object Diagnostics.ProcessStartInfo;$entryPsi.FileName=(Join-Path ([Environment]::SystemDirectory) 'WindowsPowerShell\v1.0\powershell.exe');$entryPsi.Arguments='-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$controller+'" -Execute -AuditRoot "'+$fixture+'" -AuditAttempt "'+$fixture+'"';$entryPsi.UseShellExecute=$false;$entryPsi.CreateNoWindow=$true;$entryPsi.RedirectStandardOutput=$true;$entryPsi.RedirectStandardError=$true;$entry=New-Object Diagnostics.Process;$entry.StartInfo=$entryPsi;[void]$entry.Start();$entryStdout=$entry.StandardOutput.ReadToEnd();$entryStderr=$entry.StandardError.ReadToEnd();$entry.WaitForExit();[IO.File]::WriteAllText($entryOut,$entryStdout,(New-Object Text.UTF8Encoding($false)));[IO.File]::WriteAllText($entryErr,$entryStderr,(New-Object Text.UTF8Encoding($false)));$entryJson=$entryStdout|ConvertFrom-Json;$trace.Add([pscustomobject]@{phase='saved_controller_entrypoint';command=$entryPsi.Arguments;exit_code=$entry.ExitCode;stdout_sha256=(Get-Hash $entryOut);stderr_sha256=(Get-Hash $entryErr);result_stage=$entryJson.stage;fixture_rejected=($entry.ExitCode -ne 0)})

    $expected=@{account_login=1301910045;server='XMGlobal-MT5 6';company='XM Global Limited';terminal_path='C:\fixture\terminal64.exe';terminal_data_path='C:\fixture\terminal-data'};$h='a'*64;$flat=[ordered]@{state='READY_FLAT_SEALED';readiness_evidence='C:\fixture\archive\readiness-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\output\result.json';readiness_sha256=$h;evidence_transaction='C:\fixture\archive\readiness-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';checked_at_utc=([DateTimeOffset]::UtcNow.AddSeconds(-1).ToString('o'));account_login=1301910045;server='XMGlobal-MT5 6';company='XM Global Limited';terminal_path=$expected.terminal_path;terminal_data_path=$expected.terminal_data_path;open_orders=0;open_positions=0;task_xml_unchanged=$true;request_sha256=$h;producer_sha256=$h;producer_process_id=7;profile='super1';ready=$true;flat=$true;identity_ready=$true;transport_ready=$true;identity_checks=[ordered]@{windows_profile=$true;a=$true;b=$true;c=$true;d=$true};permission_checks=[ordered]@{a=$true;b=$true;c=$true;d=$true;e=$true};permission=[ordered]@{state='READY'};order_transport_preflight=[ordered]@{state='PASS';checks=@('a','b','c','d');order_send_called=$false};transport_preflight_deferred=$false;evidence_nonce='aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';markets=[ordered]@{nq=[ordered]@{type='INDICES'};spx=[ordered]@{type='INDICES'}};evidence_root='C:\fixture\archive\readiness-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\output\evidence'};$flatFile=Join-Path $fixture 'flat.json';[IO.File]::WriteAllText($flatFile,($flat|ConvertTo-Json -Depth 20),(New-Object Text.UTF8Encoding($false)))
    $flatExec=Invoke-V16Child -ScriptBody "Get-Content -LiteralPath '$($flatFile.Replace("'","''"))' -Raw" -LogDirectory $logs -RunId 'fixture-flat' -TimeoutSeconds 30;$flatText=[IO.File]::ReadAllText($flatExec.stdout);$flatParsed=Test-V16FlatOutput -StdoutText $flatText -Expected $expected -SourceFileSha256 (Get-Hash $flatExec.stdout);$stopCalls=0;$flow=Invoke-V16RecoveryStateMachine -Preflight {[pscustomobject]@{status='PASS'}} -Flat {[pscustomobject]@{capture_complete=$flatExec.capture_complete;process_succeeded=$flatExec.process_succeeded;exit_observed=$flatExec.exit_observed;executor=$flatExec;stdout=$flatExec.stdout}} -FlatAdapter {[pscustomobject]@{operation_accepted=$flatParsed.operation_accepted;status=$flatParsed.status;outer=$flatParsed}} -ProofCopy {$trace.Add([pscustomobject]@{phase='proof_copy';status='FAIL';reason='fixture intentionally has no production sealed-owner proof'});[pscustomobject]@{status='FAIL'}} -ReadinessGate {throw 'must-not-readiness-after-proof-failure'} -Rollover {throw 'must-not-rollover-after-proof-failure'} -StopAssert {$stopCalls++;[pscustomobject]@{status='PASS';active_child=$false}} -PostFlat {throw 'must-not-post-flat-after-proof-failure'};$trace.Add([pscustomobject]@{phase='real_phase_state_machine';stage=$flow.stage;first_failure=$flow.first_failure;flat_calls=$flow.counts.flat_calls;rollover_calls=$flow.counts.rollover_calls;post_flat_calls=$flow.counts.post_flat_calls;stop_assertions=$flow.stop_assertions;stop_calls=$stopCalls;automatic_shutdown_verified=$flow.automatic_shutdown_verified;final_runtime_stopped=$flow.final_runtime_stopped;active_or_unknown_children=$flow.active_or_unknown_children.Count;proof_error_path_verified=($flow.stage -eq 'FAILED' -and $flow.counts.flat_calls -eq 1 -and $flow.counts.rollover_calls -eq 0 -and $flow.counts.post_flat_calls -eq 0 -and $flow.stop_assertions -eq 1 -and $flow.automatic_shutdown_verified -and $flow.final_runtime_stopped)})

    $sealedTrace=[ordered]@{phase='sealed_proof_rejection';status='NOT_RUN';reason='local fixture is intentionally not SYSTEM-owned; production sealed proof must reject it'};$secure=[IO.Path]::GetFullPath((Join-Path (Get-Location) 'work\backtest\deploy\super1_secure_task.ps1'));if(Test-Path -LiteralPath $secure -PathType Leaf){try{. $secure;$tx=Join-Path $fixture 'archive\readiness-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';New-Item -ItemType Directory -Path (Join-Path $tx 'output') -Force|Out-Null;[IO.File]::WriteAllText((Join-Path $tx 'output\result.json'),'{}',(New-Object Text.UTF8Encoding($false)));Assert-Super1SecureSealedTree -Path $tx;$sealedTrace.status='UNEXPECTED_PASS'}catch{$sealedTrace.status='PASS_REJECTED';$sealedTrace.error=$_.Exception.ToString()}}$trace.Add([pscustomobject]$sealedTrace)
    $final=[ordered]@{clean_process='PASS';production_controller_entrypoint='PASS_REJECTED_FIXTURE';full_controller_acceptance='INCOMPLETE';trace=$trace.ToArray()};if(-not [string]::IsNullOrWhiteSpace($OutputPath)){[IO.File]::WriteAllText($OutputPath,($final|ConvertTo-Json -Depth 20),(New-Object Text.UTF8Encoding($false)))}$final|ConvertTo-Json -Depth 20;exit 0
}

$root=Join-Path ([IO.Path]::GetTempPath()) ('v16-clean-e2e-parent-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root -Force|Out-Null;$childOut=Join-Path $root 'child.stdout.txt';$childErr=Join-Path $root 'child.stderr.txt';$tracePath=Join-Path $root 'trace.json';$psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName=Join-Path ([Environment]::SystemDirectory) 'WindowsPowerShell\v1.0\powershell.exe';$psi.Arguments='-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$MyInvocation.MyCommand.Path+'" -Child -OutputPath "'+$tracePath+'"';$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$p=New-Object Diagnostics.Process;$p.StartInfo=$psi;[void]$p.Start();$so=$p.StandardOutput.ReadToEnd();$se=$p.StandardError.ReadToEnd();$p.WaitForExit();[IO.File]::WriteAllText($childOut,$so,(New-Object Text.UTF8Encoding($false)));[IO.File]::WriteAllText($childErr,$se,(New-Object Text.UTF8Encoding($false)));$payload=Get-Content -LiteralPath $tracePath -Raw|ConvertFrom-Json;$result=[ordered]@{clean_process_controller_e2e=($p.ExitCode -eq 0 -and $payload.clean_process -eq 'PASS');child_pid=$p.Id;child_exit_code=$p.ExitCode;child_stdout_sha256=(Get-Hash $childOut);child_stderr_sha256=(Get-Hash $childErr);trace_path=$tracePath;trace_sha256=(Get-Hash $tracePath);full_acceptance=$payload.full_controller_acceptance;trace=$payload.trace};$result|ConvertTo-Json -Depth 20;$marker=if($result.clean_process_controller_e2e){'PASS'}else{'FAIL'};Write-Output ('V16_CLEAN_PROCESS_CONTROLLER_E2E '+$marker);if(-not $result.clean_process_controller_e2e){exit 1}
